package com.example.demo.controller;
import com.example.demo.repository.OrderRepository;import com.example.demo.service.*;import java.security.Principal;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class ShopController {private final CartService cart;private final UserService users;private final OrderRepository orders;public ShopController(CartService c,UserService u,OrderRepository o){cart=c;users=u;orders=o;}
 @GetMapping("/cart")String cart(Principal p,Model m){m.addAttribute("cart",cart.getCart(p.getName()));return "shop/cart";}
 @PostMapping("/cart/add/{id}")String add(@PathVariable Long id,@RequestParam(defaultValue="1")int quantity,Principal p,RedirectAttributes ra){try{cart.add(p.getName(),id,quantity);ra.addFlashAttribute("success","Товар добавлен в корзину");}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/products";}
 @PostMapping("/cart/items/{id}")String update(@PathVariable Long id,@RequestParam int quantity,Principal p,RedirectAttributes ra){try{cart.update(p.getName(),id,quantity);}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/cart";}
 @PostMapping("/cart/checkout")String checkout(Principal p,RedirectAttributes ra){try{cart.checkout(p.getName());ra.addFlashAttribute("success","Заказ успешно оформлен");return "redirect:/my-orders";}catch(RuntimeException e){ra.addFlashAttribute("error",e.getMessage());return "redirect:/cart";}}
 @GetMapping("/my-orders")String mine(Principal p,Model m){var u=users.findByUsername(p.getName()).orElseThrow();m.addAttribute("orders",orders.findByUserId(u.getId()).stream().filter(o->o.getStatus()!=com.example.demo.model.OrderStatus.NEW).toList());return "shop/orders";}}
